// IQ-3B governed evidence planner tests.
// Two layers: (1) controlled outcomes through an injected readEvidence (deterministic faults: denial, error,
// timeout, stale, truncation, ordering, deadlines); (2) real end-to-end planning through the real
// CapabilityService.readEvidence and the real certified sources against a fault-injected database client
// (loopback fixture client object only; no production target; no network).
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
assert.equal(process.env.SUPABASE_URL, 'http://127.0.0.1:55421');
const require = createRequire(import.meta.url);
for (const pkg of ['bullmq', 'ioredis']) {const p = require.resolve(pkg); class Inert {on() {return this;} quit() {return Promise.resolve();}} Inert.default = Inert; Inert.Redis = Inert; Inert.Queue = Inert; Inert.Worker = Inert; require.cache[p] = {id: p, filename: p, loaded: true, exports: Inert};}
globalThis.fetch = async () => {throw Error('PLANNER_TEST_NETWORK_FORBIDDEN');};
const {ensureRegistered} = await import('../dist/oyi-core/orchestration/ConversationOrchestrator.js');
