const source = fs.readFileSync('scripts/wave11-behavioural-torture-harness.mjs', 'utf8');
const {actorFor, oisContext} = new Function(`${source.slice(source.indexOf('const ids = '), source.indexOf('function expected(prompt)'))};return {actorFor,oisContext};`)();
const context = (surface, role, extra = {}) => {const actor = actorFor(role, surface), ois = oisContext(actor, surface); return {actor, oisContext: ois, input: {surface, message: 'Assess', estate_id: ois.estate_id, home_id: ois.home_id, context: {}, ...extra}, resolvedTurn: {request_id: 'planner-test', scope: {estate_id: ois.estate_id, home_id: ois.home_id, building_id: null, room_id: null}, semantic_frame: {normalizedText: 'assess'}, operation: 'list'}, legacyFallback: async () => {throw Error('NO_FALLBACK');}};};
const resident = () => context('consumer', 'resident'), facility = () => context('facility', 'facility_manager'), publicCtx = () => context('public_corporate', 'public', {thread_id: '50000000-0000-4000-8000-000000000001'});
const office = () => {const c = context('office_internal', 'ochiga_staff'); const perms = capabilityRegistry.all().filter(m => m.supported_surfaces?.includes('office_internal')).flatMap(m => m.permission_requirements || []); c.actor.permissions = [...new Set([...(c.actor.permissions || []), ...perms])]; return c;};
const homeA = resident().oisContext.home_id, homeB = actorFor('resident_b', 'consumer').home_id, estate = resident().oisContext.estate_id;
const ROOM = '21000000-0000-4000-8000-000000000002';
const SNAP = () => ({leads: {needing_attention: [{id: 'lead-1', name: 'Lead One', status: 'qualified', reason: 'stale', last_activity_at: null}], total_open: 39}, opportunities: {stale: [{id: 'opp-1', name: 'Opp One', stage: 'review', days_since_activity: 21, owner: null}]}, reports: {pending_approval: [{id: 'rep-1', title: 'Report One', submitted_by: null, submitted_at: null}]}, development: {projects: [{id: 'dev-1', name: 'Project One', status: 'planning'}]}, financial: {estates: [{estate_id: 'e1', name: 'Estate One'}]}, tasks: {open: [{id: 'task-1', title: 'Task One', status: 'open', overdue: false}]}, support: {items: [{id: 'sup-1', title: 'Case One', status: 'open'}]}, meetings: {items: [{id: 'mtg-1', title: 'Meeting One', status: 'scheduled'}]}});

// ---- fake query layer (same shape as the IQ-3A benchmark tests) ------------------------
const handlers = {}; let queries = [], writes = [], delay = 0;
const run = q => new Promise((resolve, reject) => setTimeout(() => {const h = handlers[q.table]; try {Promise.resolve(h ? h(q) : {data: [], error: null}).then(resolve, reject);} catch (e) {reject(e);}}, delay));
const matches = (rows, q) => rows.filter(r => q.filters.every(([op, k, v]) => op === 'eq' ? r[k] === v : op === 'in' ? v.includes(r[k]) : true));
db.from = table => {const q = {table, filters: [], limit: null}; queries.push(q); const b = {select() {return b;}, order() {return b;}, or() {return b;}, neq() {return b;}, lte() {return b;}, not() {return b;}, eq(k, v) {q.filters.push(['eq', k, v]); return b;}, in(k, v) {q.filters.push(['in', k, v]); return b;}, gte(k, v) {q.filters.push(['gte', k, v]); return b;}, is() {return b;}, limit(n) {q.limit = n; return b;}, maybeSingle() {return run(q).then(r => ({...r, data: Array.isArray(r.data) ? r.data[0] || null : r.data}));}, insert() {writes.push(`${table}.insert`); return b;}, update() {writes.push(`${table}.update`); return b;}, upsert() {writes.push(`${table}.upsert`); return b;}, delete() {writes.push(`${table}.delete`); return b;}, then(res, rej) {return run(q).then(res, rej);}}; return b;};
db.rpc = () => {writes.push('rpc'); return Promise.resolve({data: null, error: null});};
const reset = () => {for (const k of Object.keys(handlers)) delete handlers[k]; queries = []; writes = []; delay = 0;};
const table = (name, rows, error = null) => {handlers[name] = q => error ? {data: null, error} : {data: matches(rows(), q).slice(0, q.limit || undefined), error: null};};
const results = [];
const check = async (id, fn) => {reset(); try {await fn(); results.push({id, status: 'PASS'});} catch (error) {error.message = `${id}: ${error.message}`; throw error;}};

// ---- controlled outcomes -------------------------------------------------------------
const scopeOf = ctx => ({estate_id: ctx.oisContext.estate_id, building_id: null, home_id: ctx.oisContext.home_id, room_id: null});
const rec = (id, o = {}) => ({evidence_id: id, domain: 'maintenance', type: 't', object_type: 'x', object_id: id, object_ref: {object_type: 'x', object_id: id, label: `Label ${id}`}, source: 'domain_adapter', source_type: 'database', source_id: id, observed_at: null, persisted_at: null, freshness: 'unknown', truth_class: 'source_record', privacy_class: 'household_private', permissions: [], authorised_scope: {estate_id: null, home_id: null, room_id: null}, confidence: 0.5, payload: {fact: {value: {status: 'open', title: `Title ${id}`}, object: {label: `Label ${id}`}}}, ...o});
const out = (key, kind, n = 2, extra = {}) => {
  const base = {capability_key: key, domain: 'maintenance', requested_scope: {estate_id: null, building_id: null, home_id: null, room_id: null}, effective_scope: {estate_id: null, building_id: null, home_id: null, room_id: null}, authority: 'allowed', scope: 'enforced', query_executed: true, availability: 'available', population: 'p', complete: false, truncated: false, freshness: 'current', records: []};
  const records = Array.from({length: n}, (_, i) => rec(`${key}-${i}`));
  switch (kind) {
    case 'partial': return evidenceReadOutcome({...base, records, ...extra});
    case 'complete': return evidenceReadOutcome({...base, records, complete: true, ...extra});
    case 'zero': return evidenceReadOutcome({...base, records: [], complete: true, ...extra});
    case 'truncated': return evidenceReadOutcome({...base, records, truncated: true, ...extra});
    case 'stale': return evidenceReadOutcome({...base, records, complete: true, freshness: 'stale', ...extra});
    case 'denied': return evidenceReadOutcome({...base, authority: 'denied'});
    case 'unsupported': return evidenceReadOutcome({...base, scope: 'unsupported'});
    case 'error': return evidenceReadOutcome({...base, availability: 'error'});
    case 'timeout': return evidenceReadOutcome({...base, availability: 'timeout'});
    default: throw Error(kind);
  }
};
const stub = (plan = {}, fallback = 'partial') => {const calls = []; const fn = async (key, ctx, ms) => {calls.push({key, ctx, ms}); const p = plan[key]; const v = typeof p === 'function' ? await p(ctx) : p; return v ? (typeof v === 'string' ? out(key, v) : v) : out(key, fallback);}; fn.calls = calls; return fn;};
const req = (ctx, o = {}) => ({actor: ctx.actor, oisContext: ctx.oisContext, input: ctx.input, resolvedTurn: ctx.resolvedTurn, objective: 'assess', subject_domains: defaultAssessmentSubject(ctx.input.surface), subject_label: null, target_id: null, broad: true, room: {status: 'none'}, building_label: null, raw_text: 'What needs attention?', material_text: null, previous: null, ...o});
const keys = state => state.contributions.map(c => c.source_key);
const cls = (state, id) => state.classes.find(c => c.class === id);
const allow = () => ({allowed: true, reason: null});

// ================== PLAN CONSTRUCTION ===============================================
await check('planner:single-source-plan', async () => {const c = resident(); const r = await planAndGatherEvidence({...req(c, {subject_domains: ['maintenance'], broad: false}), deps: {readEvidence: stub()}}); assert.deepEqual(r.plan.steps.map(s => s.source_key), ['maintenance.requests.read']); assert.equal(r.plan.steps[0].necessity, 'mandatory'); assert.equal(r.state.stats.sources_attempted, 1);});
await check('planner:multi-source-plan-oma-broad-attention', async () => {const c = office(); const read = stub(); const r = await planAndGatherEvidence({...req(c), deps: {readEvidence: read}}); assert.deepEqual(r.plan.steps.map(s => s.source_key), ['crm.leads.read', 'crm.opportunities.read', 'development.status.read', 'reports.approvals.read', 'financial.summary.read', 'office_tasks.query.read', 'office_support.query.read', 'office_meetings.query.read']); assert.equal(read.calls.length, 8);});
await check('planner:mandatory-vs-optional-and-objective-gating', async () => {const c = office(); const explain = await planAndGatherEvidence({...req(c, {objective: 'explain'}), deps: {readEvidence: stub()}}); assert.equal(explain.plan.steps.length, 5); assert(explain.plan.steps.every(s => s.necessity === 'mandatory')); const assess = await planAndGatherEvidence({...req(c), deps: {readEvidence: stub()}}); assert.equal(assess.plan.steps.filter(s => s.necessity === 'optional').length, 3);});
await check('planner:optional-unavailable-never-blocks-and-is-reported-distinctly', async () => {const c = office(); const r = await planAndGatherEvidence({...req(c), deps: {readEvidence: stub({'office_tasks.query.read': 'error', 'office_support.query.read': 'denied', 'office_meetings.query.read': 'timeout'}, 'complete')}}); assert.equal(r.state.status, 'MANDATORY_COMPLETE_ENOUGH'); assert.deepEqual(r.state.optional_unavailable.sort(), ['office_meetings', 'office_support', 'office_tasks']); assert.equal(cls(r.state, 'office_tasks').status, 'OPTIONAL_UNAVAILABLE');});
await check('planner:partial-only-plan-is-first-class', async () => {const r = await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub({}, 'partial')}}); assert.equal(r.state.status, 'MANDATORY_PARTIAL'); assert(r.state.classes.filter(c => c.necessity === 'mandatory').every(c => c.status === 'MANDATORY_PARTIAL')); assert(r.state.cannot_conclude.some(s => /bounded, supplied view/.test(s))); assert(!/MANDATORY_COMPLETE_ENOUGH/.test(JSON.stringify(r.state.classes.filter(c => c.necessity === 'mandatory'))));});
await check('planner:all-allowed-sources-succeed-complete-enough', async () => {const r = await planAndGatherEvidence({...req(resident(), {subject_domains: ['maintenance', 'security'], broad: false}), deps: {readEvidence: stub({}, 'zero')}}); assert.equal(r.state.status, 'MANDATORY_COMPLETE_ENOUGH'); assert.deepEqual(r.state.missing_mandatory, []);});
await check('planner:missing-mandatory-capability-recorded-not-fabricated', async () => {const read = stub(); const r = await planAndGatherEvidence({...req(resident(), {subject_domains: ['utilities'], broad: false}), deps: {readEvidence: read}}); assert.equal(r.state.status, 'MANDATORY_MISSING_CAPABILITY'); assert.equal(read.calls.length, 0, 'no substitute source is read'); assert.deepEqual(r.state.missing_mandatory, ['utilities_usage']); assert(r.state.cannot_conclude.some(s => /electricity consumption/.test(s))); const text = composeEvidenceReadiness(r.state); assert(/Not available in Oyi yet/.test(text)); assert(/cannot claim anything about them/.test(text)); assert(!/I checked the evidence/.test(text), 'must not imply the missing evidence was checked');});
await check('planner:uncertified-existing-capabilities-are-never-selected', async () => {for (const subject of ['wallet']) {const read = stub(); const r = await planAndGatherEvidence({...req(resident(), {subject_domains: [subject], broad: false}), deps: {readEvidence: read}}); assert.equal(read.calls.length, 0); assert.equal(r.state.status, 'MANDATORY_MISSING_CAPABILITY'); assert(/no_certified_source/.test(cls(r.state, subject).reason));} const r = await planAndGatherEvidence({...req(resident()), deps: {readEvidence: stub()}}); assert(!r.plan.steps.some(s => /^(?:wallet|utilities)\./.test(s.source_key)));});
await check('planner:catalogue-sources-are-exactly-the-iq3a-certified-or-explicit-debt', async () => {
  const inventory = JSON.parse(fs.readFileSync('artifacts/intelligence-quality-v1-evidence-source-inventory.json', 'utf8')).records; const certified = new Set(inventory.filter(r => r.planner_eligible).map(r => r.capability_key));
  const uncertifiedListed = new Set();
  for (const e of Object.values(EVIDENCE_CLASSES)) for (const k of e.sources) {const m = capabilityRegistry.get(k); assert(m, k); if (m.evidence_read) assert(certified.has(k), `${k} opted in but absent from the certified inventory`); else uncertifiedListed.add(k);}
  assert.deepEqual([...uncertifiedListed].sort(), ['utilities.active.read', 'utilities.tariff.read', 'wallet.balance.read', 'wallet.transactions.read']);
});
await check('planner:authority-denied-at-plan-time-is-recorded-not-planned', async () => {const read = stub(); const r = await planAndGatherEvidence({...req(office()), deps: {readEvidence: read, canUse: key => key === 'financial.summary.read' ? {allowed: false, reason: 'missing_permission'} : allow()}}); assert(!keys(r.state).includes('financial.summary.read')); assert(r.plan.unresolved.some(u => u.class === 'office_financial' && u.reason === 'not_authorised')); assert.equal(cls(r.state, 'office_financial').status, 'MANDATORY_UNAVAILABLE'); assert(!read.calls.some(c => c.key === 'financial.summary.read'));});
await check('planner:authority-changed-after-planning-denies-only-that-source', async () => {const r = await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub({'reports.approvals.read': 'denied'}, 'partial'), canUse: allow}}); const reports = r.state.contributions.find(c => c.source_key === 'reports.approvals.read'); assert.equal(reports.availability, 'denied'); assert.equal(reports.record_count, 0); assert.equal(reports.material.length, 0); assert(r.state.contributions.filter(c => c.source_key !== 'reports.approvals.read').every(c => c.availability === 'available'), 'other sources unaffected'); assert.equal(r.state.stats.denied, 1);});
await check('planner:real-authority-recheck-at-execution-with-real-service', async () => {
  // Plan-time check is bypassed (stale permission snapshot); the real CapabilityService still denies at execution.
  const c = resident(); c.actor.permissions = []; c.actor.permission_scopes = []; c.actor.role = 'guest'; c.oisContext = {...c.oisContext, role: 'guest', permissions: []}; table('maintenance_requests', () => [{id: 'm1', estate_id: estate, home_id: homeA, title: 'Leak', status: 'open', created_at: new Date().toISOString()}]);
  const r = await planAndGatherEvidence({...req(c, {subject_domains: ['maintenance'], broad: false}), deps: {canUse: allow}}); const k = r.state.contributions[0]; assert.equal(k.availability, 'denied'); assert.equal(k.record_count, 0); assert(!JSON.stringify(r.state).includes('Leak')); assert(!queries.some(q => q.table === 'maintenance_requests'), 'a denied source is never queried');
});
await check('planner:failure-modes-are-isolated-and-distinct', async () => {
  const r = await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub({'crm.leads.read': 'error', 'development.status.read': 'timeout', 'office_tasks.query.read': 'stale', 'reports.approvals.read': 'truncated', 'financial.summary.read': 'zero'}, 'partial')}});
  const by = Object.fromEntries(r.state.contributions.map(c => [c.source_key, c]));
  assert.equal(by['crm.leads.read'].availability, 'error'); assert.equal(by['development.status.read'].availability, 'timeout'); assert.equal(by['office_tasks.query.read'].status, 'stale'); assert.equal(by['reports.approvals.read'].truncated, true); assert.equal(by['financial.summary.read'].completeness, 'zero_proven');
  assert.equal(cls(r.state, 'crm').status, 'MANDATORY_PARTIAL', 'one of two crm sources failed: partial, not unavailable'); assert.equal(cls(r.state, 'office_development').status, 'MANDATORY_UNAVAILABLE'); assert.equal(r.state.status, 'MANDATORY_UNAVAILABLE'); assert.equal(r.state.stats.error + r.state.stats.timeout, 2);
  assert.equal(cls(r.state, 'office_financial').status, 'MANDATORY_COMPLETE_ENOUGH'); assert.equal(cls(r.state, 'office_tasks').status, 'OPTIONAL_GATHERED');
});
await check('planner:both-sources-of-a-class-failing-is-unavailable', async () => {const r = await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub({'crm.leads.read': 'error', 'crm.opportunities.read': 'timeout'}, 'partial')}}); assert.equal(cls(r.state, 'crm').status, 'MANDATORY_UNAVAILABLE');});
await check('planner:all-sources-of-a-mandatory-class-failing-is-unavailable-not-zero', async () => {const r = await planAndGatherEvidence({...req(resident(), {subject_domains: ['maintenance'], broad: false}), deps: {readEvidence: stub({'maintenance.requests.read': 'error'})}}); assert.equal(r.state.status, 'MANDATORY_UNAVAILABLE'); assert.equal(r.state.contributions[0].completeness, 'unknown'); assert(!/none found/.test(composeEvidenceReadiness(r.state)));});
await check('planner:stale-state-is-reported-stale-for-state-classes-only', async () => {const stale = await planAndGatherEvidence({...req(resident(), {subject_domains: ['devices'], broad: false}), deps: {readEvidence: stub({'devices.status.read': 'stale'})}}); assert.equal(stale.state.contributions[0].freshness, 'stale'); assert.equal(cls(stale.state, 'device_availability').status, 'MANDATORY_PARTIAL'); const rec2 = await planAndGatherEvidence({...req(resident(), {subject_domains: ['maintenance'], broad: false}), deps: {readEvidence: stub({'maintenance.requests.read': 'stale'})}}); assert.equal(rec2.state.contributions[0].freshness, 'current', 'an old ticket is lifecycle, not a stale read');});
await check('planner:unobserved-device-state-is-partial-not-complete', async () => {const o = out('devices.status.read', 'complete', 2); o.records = o.records.map(r => ({...r, freshness: 'unobservable'})); const r = await planAndGatherEvidence({...req(resident(), {subject_domains: ['devices'], broad: false}), deps: {readEvidence: stub({'devices.status.read': o})}}); assert.equal(r.state.contributions[0].unobserved, 2); assert.equal(cls(r.state, 'device_availability').status, 'MANDATORY_PARTIAL'); assert(/unknown state/.test(composeEvidenceReadiness(r.state)));});
await check('planner:deterministic-ordering-regardless-of-completion-order', async () => {
  const slowFirst = {'crm.leads.read': async () => {await new Promise(r => setTimeout(r, 40)); return out('crm.leads.read', 'partial');}, 'financial.summary.read': async () => out('financial.summary.read', 'partial')};
  const a = await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub(slowFirst)}}); const b = await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub({})}});
  assert.deepEqual(keys(a.state), keys(b.state)); assert.deepEqual(keys(a.state), a.plan.steps.map(s => s.source_key));
  const strip = s => JSON.stringify({...s, plan_id: 0, gathered_at: 0, expires_at: 0, stats: 0, contributions: s.contributions.map(c => ({...c, gathered_at: 0, fresh_until: 0, latency_ms: 0, evidence_id: 0}))}); assert.equal(strip(a.state).replace(/"id":"[^"]*"/g, ''), strip(b.state).replace(/"id":"[^"]*"/g, ''));
});
await check('planner:fan-out-bound-keeps-mandatory-drops-optional-first', async () => {const read = stub(); const r = await planAndGatherEvidence({...req(office()), limits: {...PLANNER_LIMITS, max_sources: 6}, deps: {readEvidence: read}}); assert.equal(read.calls.length, 6); assert(r.plan.steps.every(s => s.necessity === 'mandatory' || r.plan.steps.length <= 6)); assert.equal(r.plan.steps.filter(s => s.necessity === 'optional').length, 1); assert.equal(r.plan.unresolved.filter(u => u.reason === 'fan_out_bound').length, 2); const tight = await planAndGatherEvidence({...req(office()), limits: {...PLANNER_LIMITS, max_sources: 3}, deps: {readEvidence: stub()}}); assert.equal(tight.plan.steps.length, 3); assert(tight.plan.steps.every(s => s.necessity === 'mandatory'));});
await check('planner:never-queries-the-whole-registry-or-optional-by-capacity', async () => {for (const ctx of [office(), resident(), facility(), publicCtx()]) {const read = stub(); const r = await planAndGatherEvidence({...req(ctx), deps: {readEvidence: read}}); assert(read.calls.length <= PLANNER_LIMITS.max_sources, `${ctx.input.surface}: ${read.calls.length}`); assert(read.calls.length < capabilityRegistry.all().filter(m => m.risk_class === 'read').length / 4);}});
await check('planner:overall-deadline-bounds-wall-time-and-discards-late-results', async () => {
  const slow = async key => {await new Promise(r => setTimeout(r, 300)); return out(key, 'partial');}; const t0 = Date.now();
  const r = await planAndGatherEvidence({...req(office()), limits: {...PLANNER_LIMITS, overall_ms: 60, per_source_ms: 1000}, deps: {readEvidence: stub(Object.fromEntries(['crm.leads.read', 'crm.opportunities.read', 'development.status.read', 'reports.approvals.read', 'financial.summary.read', 'office_tasks.query.read', 'office_support.query.read', 'office_meetings.query.read'].map(k => [k, () => slow(k)])))}});
  assert(Date.now() - t0 < 250, `wall ${Date.now() - t0}ms must be bounded by the overall deadline, not the sum`); assert(r.state.contributions.every(c => c.status === 'timeout')); assert.equal(r.state.status, 'MANDATORY_UNAVAILABLE');
  const snap = JSON.stringify(r.state.contributions.map(c => [c.source_key, c.status, c.record_count])); await new Promise(res => setTimeout(res, 450)); assert.equal(JSON.stringify(r.state.contributions.map(c => [c.source_key, c.status, c.record_count])), snap, 'late results never change a delivered result');
});
await check('planner:parallel-wall-time-is-the-slowest-source-not-the-sum', async () => {const slow = key => async () => {await new Promise(r => setTimeout(r, 60)); return out(key, 'partial');}; const t0 = Date.now(); await planAndGatherEvidence({...req(office()), deps: {readEvidence: stub(Object.fromEntries(['crm.leads.read', 'crm.opportunities.read', 'development.status.read', 'reports.approvals.read', 'financial.summary.read'].map(k => [k, slow(k)])))}}); assert(Date.now() - t0 < 200, `${Date.now() - t0}ms`);});

// ================== REUSE / INVALIDATION ===========================================
const first = async (ctx, o = {}) => {const read = stub({}, 'partial'); const r = await planAndGatherEvidence({...req(ctx, o), deps: {readEvidence: read, canUse: allow}}); return {r, read};};
